create table if not exists public.site_content (
  content_key text primary key,
  section text not null,
  label text not null,
  content_type text not null check (content_type in ('text','textarea','email','tel','url','number','boolean','json')),
  value jsonb not null,
  default_value jsonb not null,
  constraints jsonb not null default '{}'::jsonb,
  sort_order integer not null default 0,
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);

create table if not exists public.site_content_history (
  id bigint generated always as identity primary key,
  content_key text not null references public.site_content(content_key) on delete cascade,
  previous_value jsonb not null,
  changed_by uuid references auth.users(id) on delete set null,
  changed_at timestamptz not null default now()
);

create index if not exists site_content_section_sort_idx on public.site_content(section, sort_order);
create index if not exists site_content_history_key_date_idx on public.site_content_history(content_key, changed_at desc);
create index if not exists site_content_history_changed_by_idx on public.site_content_history(changed_by);

alter table public.site_content enable row level security;
alter table public.site_content_history enable row level security;

drop policy if exists "Public reads site content" on public.site_content;
create policy "Public reads site content" on public.site_content for select to anon, authenticated using (true);

drop policy if exists "Admins update site content" on public.site_content;
create policy "Admins update site content" on public.site_content for update to authenticated
using (exists(select 1 from public.site_admins where user_id = (select auth.uid())))
with check (exists(select 1 from public.site_admins where user_id = (select auth.uid())));

drop policy if exists "Admins read content history" on public.site_content_history;
create policy "Admins read content history" on public.site_content_history for select to authenticated
using (exists(select 1 from public.site_admins where user_id = (select auth.uid())));

drop policy if exists "Admins write content history" on public.site_content_history;
create policy "Admins write content history" on public.site_content_history for insert to authenticated
with check (exists(select 1 from public.site_admins where user_id = (select auth.uid())) and changed_by = (select auth.uid()));

grant select on public.site_content to anon, authenticated;
grant update on public.site_content to authenticated;
grant select, insert on public.site_content_history to authenticated;
grant usage, select on sequence public.site_content_history_id_seq to authenticated;

