('services.items','Servicios','Servicios publicados','json',
 '[{"id":"mantenimiento","title":"Mantenimiento de cubiertas y fachadas","shortTitle":"Mantenimientos","subtitle":"Propiedad horizontal","intro":"Mantenimientos enfocados en mejorar el bienestar y seguridad para tu propiedad horizontal.","paragraphs":["Para garantizar el bienestar, construyendo e impermeabilizando la seguridad para resguardar tu hogar, zonas comunes, zonas de trabajo y oficinas, que harán de tu unidad un gran lugar para vivir.","Protección para fachadas, cubiertas y estructuras expuestas a la intemperie, de ladrillo, bloques de cemento, piedras naturales o artificiales, terrazas, parqueaderos, plazoletas y demás, para reducir y eliminar las eflorescencias y el deterioro de su acabado tanto interior como exterior."],"promise":"Protege y garantiza tu patrimonio.","visible":true},{"id":"construccion","title":"Construcción de obras civiles y arquitectónicas","shortTitle":"Construcción","subtitle":"Vivienda campestre, hoteles, bodegas industriales, remodelación de locales comerciales y oficina abierta.","intro":"Construcción de proyectos de infraestructura civil y arquitectónica. Construyendo identidad.","paragraphs":["Garantizamos la estabilidad de tu legado, construyendo espacios equilibrados, gracias a la unión de la arquitectura y la ingeniería civil, que harán de tu proyecto un gran lugar para vivir.","Para mejorar la producción y el almacenamiento de las compañías, para garantizar un bienestar humano con una óptima integración entre la espacialidad, el colaborador y las máquinas, mejorando la tranquilidad y nuestra libertad, para una vida sin igual, que marca un precedente en tu hogar."],"promise":"Construyendo tu bienestar y experiencias para contar.","visible":true},{"id":"servicios-profesionales","title":"Servicios profesionales","shortTitle":"Servicios profesionales","subtitle":"Consultoría, interventoría y dirección de proyectos de infraestructura civil y arquitectónica.","intro":"Conformada por un equipo de trabajo profesional de la construcción, arquitectura e ingeniería civil.","paragraphs":["El diseño debe satisfacer las necesidades de espacios habitables para tu proyecto, tanto en lo estético como en lo tecnológico, para tu hogar, industria y ambientes corporativos.","Consolidar proyectos de infraestructura que serán desarrollados de acuerdo con la planificación y acorde con su presupuesto, de la mano de la arquitectura y de ingeniería civil y ambiental.","Para coordinar y controlar que el proceso constructivo se edifique en concordancia con los diseños y especificaciones técnicas determinadas."],"promise":"Arquitectura e ingeniería civil.","visible":true}]',
